mapper.select:
SELECT EXISTS (
    SELECT 1 FROM public.tenant_invitations
    WHERE tenant_key   = #{tenantKey}
      AND invited_email = #{invitedEmail}
      AND status        = 'PENDING'
)

mapper.update:
UPDATE public.tenant_invitations
SET status     = #{status},
    updated_at = #{updatedAt}
WHERE id = #{id}

UPDATE public.tenant_invitations
SET status      = 'ACCEPTED',
    accepted_at = #{acceptedAt},
    updated_at  = #{updatedAt}
WHERE id = #{id}

UPDATE public.tenant_invitations
SET status     = 'EXPIRED',
    updated_at = #{updatedAt}
WHERE status    = 'PENDING'
  AND expires_at < #{now}
